                int backward_edges = 0;
                if (path_length != -1) {
                    int curr = t;
                    while(curr != s){

                        bool found = false;
                        for(auto& edge : directed_edges){
                            if(edge.first == curr && edge.second == parent[curr]){
                                found = true;
                                break;
                            }
                        }
                        if(!found){
                            backward_edges++;
                        }

                        curr = parent[curr];

                    }
                }

                d_sum += backward_edges;
            }
        }


        if(count == 0 || d_sum < count){
            count = d_sum;
        }

    }


    if (n == 4){
