                        int min_outer = 10;
                        for (int i = r1; i <= r2; ++i) {
                            for (int j = c1; j <= c2; ++j) {
                                if (i == r1 || i == r2 || j == c1 || j == c2) {
                                    min_outer = min(min_outer, grid[i][j]);
                                }
                            }
                        }

                        int max_inner = -1;
                        for (int i = r1 + 1; i < r2; ++i) {
                            for (int j = c1 + 1; j < c2; ++j) {
