            new_input |= neighbors[3] << 2;
            new_input |= neighbors[4] << 1;
            new_input |= neighbors[5] << 0;

            int second_output = filter[new_input] - '0';

            if (output != second_output) {
                idempotent = false;
                break;
            }
        }

        if (idempotent) {
            cout << "yes" << endl;
        } else {
            cout << "no" << endl;
        }
