        adj[edges[i].second].push_back(edges[i].first);
    }

    for (int i = 0; i < q; ++i) {
        int type;
        cin >> type;

        if (type == 1) {
            int v;
            cin >> v;

            vector<bool> visited(n + 1, false);
            vector<int> reachable_nodes;
            vector<int> q_nodes;
            q_nodes.push_back(v);
            visited[v] = true;

            int head = 0;
            while (head < q_nodes.size()) {
                int u = q_nodes[head++];
                reachable_nodes.push_back(u);

                for (int neighbor : adj[u]) {
                    if (!visited[neighbor]) {
                        visited[neighbor] = true;
                        q_nodes.push_back(neighbor);
                    }
                }
            }

            int max_val = 0;
            int max_node = -1;
            for (int node : reachable_nodes) {
                if (p[node] > max_val) {
                    max_val = p[node];
                    max_node = node;
                }
            }

            if (max_node != -1) {
                cout << max_val << endl;
                p[max_node] = 0;
            } else {
