            int v = edges[i].second;

            auto it_u = find(adj[u].begin(), adj[u].end(), v);
            if (it_u != adj[u].end()) {
                adj[u].erase(it_u);
            }

            auto it_v = find(adj[v].begin(), adj[v].end(), u);
            if (it_v != adj[v].end()) {
                adj[v].erase(it_v);
            }
        }
    }

    return 0;
}

