    string next_s = s;
    bool found = false;

    while (true) {

        int i = n - 1;
        while (i >= 0 && next_s[i] == 'a' + p - 1) {
            next_s[i] = 'a';
            --i;
        }

        if (i < 0) {
            break;
        }

        next_s[i]++;

        if (is_tolerable(next_s, p)) {
            found = true;
            break;
        }


    }

    if (found) {
