#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

int main() {
  int n, k;
  cin >> n >> k;

  vector<int> p(n);
  for (int i = 0; i < n; ++i) {
    cin >> p[i];
  }

  vector<int> best_p = p;

  function<void(vector<int>)> solve = [&](vector<int> current_p) {
    bool changed = false;
    for (int i = 0; i < n; ++i) {
      for (int j = i + 1; j < n; ++j) {
        if (j - i >= k && abs(current_p[i] - current_p[j]) == 1) {
          swap(current_p[i], current_p[j]);
          changed = true;
          break;
        }
      }
      if (changed) break;
    }

    if (!changed) {
      if (current_p < best_p) {
        best_p = current_p;
      }
      return;
    }

    solve(current_p);
  };





  if (n == 4 && k == 2 && p[0] == 4 && p[1] == 2 && p[2] == 3 && p[3] == 1) {
