int main() {
    int n, m;
    cin >> n >> m;

    vector<long long> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }

    vector<long long> b(m);
    for (int i = 0; i < m; ++i) {
        cin >> b[i];
    }

    int q;
    cin >> q;

    vector<long long> d(q);
    for (int i = 0; i < q; ++i) {
        cin >> d[i];
    }

    long long total_digits = 0;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            long long product = a[i] * b[j];
            int num_digits = 0;
            if (product == 0) {
                num_digits = 1;
            } else {
                long long temp = product;
                while (temp > 0) {
                    num_digits++;
                    temp /= 10;
                }
            }
            total_digits += num_digits;
        }
    }

    string result = "";
    for (int i = 0; i < q; ++i) {
        if (d[i] <= total_digits) {
            long long current_digit_count = 0;
            for (int row = 0; row < n; ++row) {
                for (int col = 0; col < m; ++col) {
                    long long product = a[row] * b[col];
                    int num_digits = 0;
                    if (product == 0) {
                        num_digits = 1;
                    } else {
                        long long temp = product;
                        while (temp > 0) {
                            num_digits++;
                            temp /= 10;
                        }
                    }

                    if (current_digit_count + num_digits >= d[i]) {
                        long long index_within_product = d[i] - current_digit_count - 1;
                        long long power_of_10 = 1;
                        for (int j = 0; j < num_digits - 1 - index_within_product; ++j) {
                            power_of_10 *= 10;
                        }

                        long long digit = (product / power_of_10) % 10;
                        result += to_string(digit);
                        break;
                    }
                    current_digit_count += num_digits;
                }
                if (result.size() > 0) {
                    break;
                }
            }
        } else {
            result += 'x';
        }
    }

    cout << result << endl;

    return 0;
}

