    for (int i = 0; i < k; ++i) {
        cin >> forbidden_pairs[i].first >> forbidden_pairs[i].second;
    }

    int n = s.length();
    int min_removed = n;

    for (int i = 0; i < (1 << n); ++i) {
        string sub = "";
        int removed_count = 0;
        for (int j = 0; j < n; ++j) {
            if ((i >> j) & 1) {
                sub += s[j];
            } else {
                removed_count++;
            }
        }

        bool valid = true;
        for (int j = 0; j < sub.length() - 1; ++j) {
            bool found = false;
            for (int l = 0; l < k; ++l) {
                if ((sub[j] == forbidden_pairs[l].first && sub[j + 1] == forbidden_pairs[l].second) ||
                    (sub[j] == forbidden_pairs[l].second && sub[j + 1] == forbidden_pairs[l].first)) {
                    found = true;
                    break;
                }
            }
            if (found) {
                valid = false;
                break;
            }
        }

        if (valid) {
            min_removed = min(min_removed, removed_count);
        }
    }

    cout << min_removed << endl;

    return 0;
}

