bool is_k_good(int n, int k) {
  string s = to_string(n);
  for (int i = 0; i < s.length(); ++i) {
    int digit = s[i] - '0';
    if (digit > k) {
      return false;
    }
  }
  for (int i = 0; i <= k; ++i) {
    bool found = false;
    for (int j = 0; j < s.length(); ++j) {
      if (s[j] - '0' == i) {
        found = true;
        break;
      }
    }
    if (!found) {
      return false;
    }
  }
  return true;
}

