        F[0] = 1;
        F[1] = 1;
        for (int i = 2; i <= V + 1; ++i) {
            F[i] = (F[i - 1] + F[i - 2]) % 1001;
        }

        vector<vector<int>> adj(V + 1);
        for (int i = 1; i <= V; ++i) {
            for (int j = i + 1; j <= V; ++j) {
                if (abs(F[i] - F[j]) < d) {
                    adj[i].push_back(j);
                    adj[j].push_back(i);
                }
            }
        }

        vector<bool> visited(V + 1, false);
