                visited[i] = true;

                int head = 0;
                while (head < q.size()) {
                    int u = q[head++];
                    for (int v : adj[u]) {
                        if (!visited[v]) {
                            visited[v] = true;
                            q.push_back(v);
                        }
                    }
                }
            }
        }

