    }

    int min_changed = n;

    for (int l = 0; l <= 1000; ++l) {
        for (int r = l; r <= 1000; ++r) {
            vector<int> compressed_a(n);
            int changed_count = 0;
            for (int j = 0; j < n; ++j) {
                if (a[j] < l) {
                    compressed_a[j] = l;
