            vector<int> distinct_values;
            for (int j = 0; j < n; ++j) {
                bool found = false;
                for (int k = 0; k < distinct_values.size(); ++k) {
                    if (distinct_values[k] == compressed_a[j]) {
                        found = true;
                        break;
                    }
