                digit = c - '0';
            } else {
                digit = c - 'A' + 10;
            }
            if (digit >= radix) {
                minutes = -1;
                break;
            }
            minutes = minutes * radix + digit;
        }

        if (hours >= 0 && hours <= 23 && minutes >= 0 && minutes <= 59) {
            valid_radix.push_back(radix);
