        cin >> friends[i].first >> friends[i].second;
    }

    long long max_friendship = 0;
    for (int i = 0; i < (1 << n); ++i) {
        vector<int> money;
        long long current_friendship = 0;

        for (int j = 0; j < n; ++j) {
            if ((i >> j) & 1) {
                money.push_back(friends[j].first);
