            }
        }

        bool valid = true;
        for (size_t j = 0; j < money.size(); ++j) {
            for (size_t k = 0; k < money.size(); ++k) {
                if (j != k && money[k] >= money[j] + d) {
                    valid = false;
                    break;
                }
            }
            if (!valid) break;
        }

        if (valid) {
            max_friendship = max(max_friendship, current_friendship);
        }
    }

    cout << max_friendship << endl;

    return 0;
}

