using namespace std;

long long baseToDecimal(const vector<int>& digits, int base) {
    long long result = 0;
    long long power = 1;
    for (int i = digits.size() - 1; i >= 0; --i) {
        result += digits[i] * power;
        power *= base;
    }
    return result;
}

