  }

  long long max_joy = 0;
  vector<vector<int>> distributions(n);
  vector<bool> used(n * k, false);

  function<void(int, int)> solve = [&](int player_index, int cards_distributed) {
    if (player_index == n) {
      if (cards_distributed == n * k) {
        vector<long long> player_joys(n);
        for (int i = 0; i < n; ++i) {
